CODE="import os,itertools\nSQ=chr(39)\nbase='https://notarypublic.istanbul'\nlangs=['','tr/','ru/','ar/','zh/']\ncodes={'':'en','tr/':'tr','ru/':'ru','ar/':'ar','zh/':'zh-Hans'}\npages=['index.html','faq.html','e-apostille.html','getting-married-in-turkey.html','reviews.html']\nfor p,lp in itertools.product(pages,langs):\n@fp=lp+p\n@if not os.path.exists(fp):\n@@print('SKIP (not found): '+fp); continue\n@c=open(fp,encoding='utf-8').read()\n@if 'hreflang' in c:\n@@print('SKIP (already has hreflang): '+fp); continue\n@if '</head>' not in c:\n@@print('SKIP (no head tag): '+fp); continue\n@parts=[]\n@for l in langs:\n@@u=base+'/'+l if p=='index.html' else base+'/'+l+p\n@@parts.append('<link rel='+SQ+'alternate'+SQ+' hreflang='+SQ+codes[l]+SQ+' href='+SQ+u+SQ+' />')\n@du=base+'/' if p=='index.html' else base+'/'+p\n@parts.append('<link rel='+SQ+'alternate'+SQ+' hreflang='+SQ+'x-default'+SQ+' href='+SQ+du+SQ+' />')\n@block='\\n'.join(parts)\n@newc=c.replace('</head>', block+'\\n</head>', 1)\n@open(fp,'w',encoding='utf-8').write(newc)\n@print('UPDATED: '+fp)\n"; exec(CODE.replace("@"," "))